def make_mock_twincatitem(
    name, data_type, *, pragma=None, array_info=None, ads_port=851
):
    """
    Create a mock TwincatItem for testing purposes

    May require monkey-patching `walk` to create chains.
    """

    class _Property:
        name = "pytmc"
        value = str(pragma)

    class _Properties:
        Property = [_Property]

    class MockItem:
        module = types.SimpleNamespace(ads_port=ads_port)

        if pragma is not None:
            Properties = [_Properties]

    MockItem.name = name
    MockItem.array_info = array_info
    MockItem.data_type = data_type

    def walk(condition=None):
        # By default, just the item itself:
        yield [MockItem]

    MockItem.walk = walk

    if array_info is not None:

        class ArrayInfo:
            bounds = array_info
            elements = array_info[1] - array_info[0]

        MockItem.array_info = ArrayInfo
    return MockItem


def make_mock_type(
    name,
    is_array=False,
    is_enum=False,
    is_string=False,
    is_complex_type=False,
    enum_dict=None,
    length=1,
    namespace=None,
):
    if name.startswith("STRING"):
        is_string = True

    def walk(condition=None):
        for a in []:
            yield 0

    return types.SimpleNamespace(
        name=name,
        qualified_type_name=f"{namespace}.{name}" if namespace else name,
        is_array=is_array,
        is_enum=is_enum,
        is_string=is_string,
        is_complex_type=is_complex_type,
        walk=walk,
        enum_dict=enum_dict or {},
        length=length,
    )


